ALTER TABLE "jobs" ADD COLUMN "organization_id" bigint NULL;
CREATE TABLE "announcements" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "title" character varying NOT NULL, "body" text NOT NULL, "level" character varying NOT NULL DEFAULT 'info', "starts_at" timestamptz NULL, "ends_at" timestamptz NULL, "author" character varying NOT NULL, "organization_announcements" bigint NULL, PRIMARY KEY ("id"), CONSTRAINT "announcements_organizations_announcements" FOREIGN KEY ("organization_announcements") REFERENCES "organizations" ("id") ON DELETE SET NULL);
CREATE INDEX "announcement_starts_at_ends_at" ON "announcements" ("starts_at", "ends_at");
CREATE TABLE "inventories" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "name" character varying NOT NULL, "description" character varying NULL, "owner" character varying NULL, "organization_inventories" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "inventories_organizations_inventories" FOREIGN KEY ("organization_inventories") REFERENCES "organizations" ("id") ON DELETE NO ACTION);
CREATE UNIQUE INDEX "inventory_name_organization_inventories" ON "inventories" ("name", "organization_inventories");
CREATE TABLE "inventory_devices" ("inventory_id" bigint NOT NULL, "device_id" bigint NOT NULL, PRIMARY KEY ("inventory_id", "device_id"), CONSTRAINT "inventory_devices_inventory_id" FOREIGN KEY ("inventory_id") REFERENCES "inventories" ("id") ON DELETE CASCADE, CONSTRAINT "inventory_devices_device_id" FOREIGN KEY ("device_id") REFERENCES "devices" ("id") ON DELETE CASCADE);
CREATE TABLE "inventory_groups" ("inventory_id" bigint NOT NULL, "group_id" bigint NOT NULL, PRIMARY KEY ("inventory_id", "group_id"), CONSTRAINT "inventory_groups_inventory_id" FOREIGN KEY ("inventory_id") REFERENCES "inventories" ("id") ON DELETE CASCADE, CONSTRAINT "inventory_groups_group_id" FOREIGN KEY ("group_id") REFERENCES "groups" ("id") ON DELETE CASCADE);
